    if not expenses:
        return {"count": 0, "total": 0.0, "average": 0.0, "first_date": None, "last_date": None}
    dates = sorted(exp["date"] for exp in expenses)
    total = grand_total(expenses)
    return {
        "count": len(expenses),
        "total": total,
        "average": round_money(total / len(expenses)),
        "first_date": dates[0],
        "last_date": dates[-1],
    }


